style.css:
@-moz-document domain("music.youtube.com") {
/* Fondo personalizado */
  body, ytm-app {
    background-color: #1a1a2e !important; /* Puedes usar una imagen con: background-image */
    background-image: url('https://tuimagen.com/fondo.jpg'); /* Opcional */
    background-size: cover;
    background-repeat: no-repeat;
    color: #ffffff !important;
  }

  /* Cambia el color de texto global */
  *, *::before, *::after {
    color: #ffffff !important;
  }

  /* Oculta el logo original */
  ytm-logo, .logo, .ytmusic-logo {
    display: none !important;
    visibility: hidden !important;
  }

  /* Añade un logo personalizado */
  header.ytm-app-header::before {
    content: "";
    display: block;
    width: 120px;
    height: 40px;
    background-image: url('https://tuimagen.com/logo.png'); /* URL del nuevo logo */
    background-size: contain;
    background-repeat: no-repeat;
    position: absolute;
    top: 12px;
    left: 16px;
    z-index: 1000;
  }
}
